const toCamelCase = (str: string): string =>
  str.replace(/[-_\s]+(.)?/g, (_, c) => (c ? c.toUpperCase() : ""))
    .replace(/^(.)/, c => c.toLowerCase());

const uuidv4 = (): string =>
  "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    return (c === "x" ? r : (r & 0x3) | 0x8).toString(16);
  });

const randomString = (length: number, chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"): string =>
  Array.from(crypto.getRandomValues(new Uint8Array(length)))
    .map(x => chars[x % chars.length]).join("");

const dedupe = <T>(arr: T[]): T[] => [...new Set(arr)];
const dedupeBy = <T>(arr: T[], key: keyof T): T[] =>
  arr.filter((item, i, self) => self.findIndex(t => t[key] === item[key]) === i);

const groupBy = <T>(arr: T[], key: keyof T): Record<string, T[]> =>
  arr.reduce((acc, item) => {
    const k = String(item[key]);
    (acc[k] ??= []).push(item);
    return acc;
  }, {} as Record<string, T[]>);

const chunk = <T>(arr: T[], size: number): T[][] =>
  Array.from({ length: Math.ceil(arr.length / size) },
    (_, i) => arr.slice(i * size, i * size + size));

const flatDeep = <T>(arr: (T | T[])[]): T[] =>
  arr.reduce<T[]>((acc, val) =>
    Array.isArray(val) ? acc.concat(flatDeep(val)) : [...acc, val], []);

const sortByFields = <T>(arr: T[], ...fields: Array<keyof T>): T[] =>
  [...arr].sort((a, b) => {
    for (const f of fields) {
      if (a[f] < b[f]) return -1;
      if (a[f] > b[f]) return 1;
    }
    return 0;
  });

const partition = <T>(arr: T[], pred: (x: T) => boolean): [T[], T[]] =>
  arr.reduce<[T[], T[]]>(([yes, no], x) =>
    pred(x) ? [[...yes, x], no] : [yes, [...no, x]], [[], []]);

const shuffle = <T>(arr: T[]): T[] => {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

const intersection = <T>(a: T[], b: T[]): T[] => { const s = new Set(b); return a.filter(x => s.has(x)); };
const difference = <T>(a: T[], b: T[]): T[] => { const s = new Set(b); return a.filter(x => !s.has(x)); };
const union = <T>(a: T[], b: T[]): T[] => [...new Set([...a, ...b])];

const paginateArray = <T>(arr: T[], page: number, pageSize: number) => ({
  data: arr.slice((page - 1) * pageSize, page * pageSize),
  total: arr.length,
  pages: Math.ceil(arr.length / pageSize),
  page,
  pageSize,
});

const moveItem = <T>(arr: T[], from: number, to: number): T[] => {
  const a = [...arr];
  a.splice(to, 0, a.splice(from, 1)[0]);
  return a;
};

const findDuplicates = <T>(arr: T[]): T[] => {
  const seen = new Set<T>(), dupes = new Set<T>();
  for (const x of arr) seen.has(x) ? dupes.add(x) : seen.add(x);
  return [...dupes];
};

const debounce = <T extends (...args: any[]) => any>(fn: T, ms: number) => {
  let timer: ReturnType<typeof setTimeout>;
  return (...args: Parameters<T>) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
};

const throttle = <T extends (...args: any[]) => any>(fn: T, ms: number) => {
  let last = 0;
  return (...args: Parameters<T>) => {
    const now = Date.now();
    if (now - last >= ms) { last = now; fn(...args); }
  };
};

const memoize = <T extends (...args: any[]) => any>(fn: T): T => {
  const cache = new Map<string, ReturnType<T>>();
  return ((...args: Parameters<T>) => {
    const key = JSON.stringify(args);
    if (!cache.has(key)) cache.set(key, fn(...args));
    return cache.get(key)!;
  }) as T;
};

class LRUCache<K, V> {
  private cache = new Map<K, V>();
  constructor(private readonly capacity: number) {}
  get(key: K): V | undefined {
    if (!this.cache.has(key)) return undefined;
    const val = this.cache.get(key)!;
    this.cache.delete(key); this.cache.set(key, val);
    return val;
  }
  set(key: K, val: V): void {
    this.cache.delete(key);
    if (this.cache.size >= this.capacity)
      this.cache.delete(this.cache.keys().next().value!);
    this.cache.set(key, val);
  }
  get size() { return this.cache.size; }
}

const deepClone = <T>(obj: T): T => {
  if (obj === null || typeof obj !== "object") return obj;
  if (obj instanceof Date) return new Date(obj.getTime()) as unknown as T;
  if (Array.isArray(obj)) return obj.map(deepClone) as unknown as T;
  return Object.fromEntries(
    Object.entries(obj as object).map(([k, v]) => [k, deepClone(v)])
  ) as T;
};

const deepMerge = <T extends object>(target: T, ...sources: Partial<T>[]): T => {
  for (const src of sources)
    for (const [k, v] of Object.entries(src))
      (target as any)[k] = v && typeof v === "object" && !Array.isArray(v)
        ? deepMerge((target as any)[k] ?? {}, v)
        : v;
  return target;
};

const retryWithBackoff = async <T>(
  fn: () => Promise<T>,
  maxRetries = 3,
  baseMs = 300,
): Promise<T> => {
  for (let attempt = 0; ; attempt++) {
    try { return await fn(); } catch (err) {
      if (attempt >= maxRetries) throw err;
      await new Promise(r =>
        setTimeout(r, baseMs * 2 ** attempt + Math.random() * 100));
    }
  }
};

const binarySearch = <T>(arr: T[], target: T): number => {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1;
    if (arr[mid] === target) return mid;
    arr[mid] < target ? (lo = mid + 1) : (hi = mid - 1);
  }
  return -1;
};

const deepEqual = (a: unknown, b: unknown): boolean => {
  if (a === b) return true;
  if (!a || !b || typeof a !== "object" || typeof b !== "object") return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  return ka.length === kb.length && ka.every(k => deepEqual((a as any)[k], (b as any)[k]));
};

const topoSort = (graph: Map<string, string[]>): string[] => {
  const visited = new Set<string>(), result: string[] = [];
  const visit = (node: string) => {
    if (visited.has(node)) return;
    visited.add(node);
    for (const dep of graph.get(node) ?? []) visit(dep);
    result.unshift(node);
  };
  for (const node of graph.keys()) visit(node);
  return result;
};

const timeAgo = (date: Date): string => {
  const secs = Math.floor((Date.now() - date.getTime()) / 1000);
  const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });
  const table: [number, Intl.RelativeTimeFormatUnit][] = [
    [60,"second"],[3600,"minute"],[86400,"hour"],
    [2592000,"day"],[31536000,"month"],[Infinity,"year"]
  ];
  for (const [limit, unit] of table) {
    const prev = table[table.indexOf([limit,unit])-1]?.[0] ?? 1;
    if (secs < limit) return rtf.format(-Math.floor(secs / prev), unit);
  }
  return rtf.format(-Math.floor(secs / 31536000), "year");
};

const addDays = (date: Date, days: number): Date => {
  const d = new Date(date); d.setDate(d.getDate() + days); return d;
};

const businessDaysBetween = (start: Date, end: Date): number => {
  let count = 0, d = new Date(start);
  while (d < end) {
    d.setDate(d.getDate() + 1);
    const day = d.getDay();
    if (day !== 0 && day !== 6) count++;
  }
  return count;
};

const calcAge = (birthDate: Date): number => {
  const today = new Date();
  let age = today.getFullYear() - birthDate.getFullYear();
  const m = today.getMonth() - birthDate.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
  return age;
};

async function fetchWithTimeout(url: string, opts: RequestInit = {}, ms = 5000): Promise<Response> {
  const ctrl = new AbortController();
  const id = setTimeout(() => ctrl.abort(), ms);
  try { return await fetch(url, { ...opts, signal: ctrl.signal }); }
  finally { clearTimeout(id); }
}

async function fetchJson<T>(url: string, opts: RequestInit = {}, retries = 3): Promise<T> {
  for (let i = 0;;i++) {
    const res = await fetch(url, opts);
    if (res.ok) return res.json() as Promise<T>;
    if (i >= retries || res.status < 500) throw new Error(`HTTP ${res.status}`);
    await new Promise(r => setTimeout(r, 300 * 2 ** i));
  }
}

function sseClient(url: string, onMsg: (d: string) => void, onErr?: (e: Event) => void) {
  const es = new EventSource(url);
  es.onmessage = e => onMsg(e.data);
  es.onerror = e => { onErr?.(e); es.close(); };
  return { close: () => es.close() };
}

function autoWS(url: string, onMsg: (e: MessageEvent) => void, ms = 2000) {
  let ws: WebSocket;
  const connect = () => {
    ws = new WebSocket(url);
    ws.onmessage = onMsg;
    ws.onclose = () => setTimeout(connect, ms);
  };
  connect();
  return {
    send: (d: string) => ws.readyState === 1 && ws.send(d),
    close: () => ws.close(),
  };
}

import { createHmac } from "crypto";
function jwtSign(payload: object, secret: string, expSec = 3600): string {
  const enc = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
  const h = enc({ alg:"HS256", typ:"JWT" });
  const b = enc({ ...payload, iat: Math.floor(Date.now()/1000), exp: Math.floor(Date.now()/1000)+expSec });
  const sig = createHmac("sha256", secret).update(h+"."+b).digest("base64url");
  return h+"."+b+"."+sig;
}

import { createHmac } from "crypto";
function jwtVerify<T>(token: string, secret: string): T {
  const [h, b, sig] = token.split(".");
  const exp = createHmac("sha256", secret).update(h+"."+b).digest("base64url");
  if (sig !== exp) throw new Error("Invalid signature");
  const p = JSON.parse(Buffer.from(b, "base64url").toString()) as any;
  if (p.exp && p.exp < Date.now()/1000) throw new Error("Token expired");
  return p as T;
}

