import { createCipheriv, createDecipheriv, randomBytes } from "crypto";
const A = "aes-256-gcm";
export function aesEncrypt(text: string, keyHex: string): string {
  const iv = randomBytes(12), key = Buffer.from(keyHex, "hex");
  const c = createCipheriv(A, key, iv);
  const enc = Buffer.concat([c.update(text, "utf8"), c.final()]);
  return [iv, c.getAuthTag(), enc].map(b => b.toString("hex")).join(":");
}
export function aesDecrypt(data: string, keyHex: string): string {
  const [iv, tag, enc] = data.split(":").map(h => Buffer.from(h, "hex"));
  const d = createDecipheriv(A, Buffer.from(keyHex, "hex"), iv);
  d.setAuthTag(tag);
  return Buffer.concat([d.update(enc), d.final()]).toString("utf8");
}

