type Ok<T> = { ok: true; value: T };
type Err<E> = { ok: false; error: E };
type Result<T, E = Error> = Ok<T> | Err<E>;
const ok = <T>(v: T): Ok<T> => ({ ok: true, value: v });
const err = <E>(e: E): Err<E> => ({ ok: false, error: e });
async function safe<T>(fn: () => Promise<T>): Promise<Result<T>> {
  try { return ok(await fn()); }
  catch (e) { return err(e instanceof Error ? e : new Error(String(e))); }
}

type L = "debug"|"info"|"warn"|"error";
const R: Record<L,number> = { debug:0, info:1, warn:2, error:3 };
const MIN: L = (process.env.LOG_LEVEL as L) ?? "info";
export const logger = {
  write(l: L, msg: string, meta?: object) {
    if (R[l] < R[MIN]) return;
    const out = JSON.stringify({ l, msg, ts: new Date().toISOString(), ...meta });
    (l === "error" ? console.error : l === "warn" ? console.warn : console.log)(out);
  },
  info:  (m: string, x?: object) => logger.write("info",  m, x),
  warn:  (m: string, x?: object) => logger.write("warn",  m, x),
  error: (m: string, x?: object) => logger.write("error", m, x),
  debug: (m: string, x?: object) => logger.write("debug", m, x),
};

