class TTLCache<K, V> {
  private s = new Map<K, { v: V; e: number }>();
  constructor(private ms: number) {}
  set(k: K, v: V) { this.s.set(k, { v, e: Date.now() + this.ms }); }
  get(k: K): V | undefined {
    const e = this.s.get(k);
    if (!e) return;
    if (Date.now() > e.e) { this.s.delete(k); return; }
    return e.v;
  }
  del(k: K) { this.s.delete(k); }
  clear() { this.s.clear(); }
}

import { Redis } from "ioredis";
const redis = new Redis(process.env.REDIS_URL!);
export async function cached<T>(key: string, ttl: number, fn: () => Promise<T>): Promise<T> {
  const hit = await redis.get(key);
  if (hit) return JSON.parse(hit) as T;
  const v = await fn();
  await redis.set(key, JSON.stringify(v), "EX", ttl);
  return v;
}

import { Redis } from "ioredis";
const r = new Redis(process.env.REDIS_URL!);
export async function withLock<T>(key: string, ttl: number, fn: () => Promise<T>): Promise<T | null> {
  const lk = `lock:${key}`;
  if (!await r.set(lk, "1", "EX", ttl, "NX")) return null;
  try { return await fn(); } finally { await r.del(lk); }
}

import { useState, useEffect } from "react";
export function useDebounce<T>(val: T, ms: number): T {
  const [v, setV] = useState(val);
  useEffect(() => {
    const id = setTimeout(() => setV(val), ms);
    return () => clearTimeout(id);
  }, [val, ms]);
  return v;
}

import { useState, useEffect } from "react";
export function useFetch<T>(url: string) {
  const [s, set] = useState<{ data: T|null; loading: boolean; error: string|null }>
    ({ data: null, loading: true, error: null });
  useEffect(() => {
    let active = true;
    set({ data: null, loading: true, error: null });
    fetch(url)
      .then(r => r.ok ? r.json() : Promise.reject(`HTTP ${r.status}`))
      .then(d => active && set({ data: d, loading: false, error: null }))
      .catch(e => active && set({ data: null, loading: false, error: String(e) }));
    return () => { active = false; };
  }, [url]);
  return s;
}

import { useState } from "react";
export function useLocalStorage<T>(key: string, init: T): [T, (v: T) => void] {
  const [s, set] = useState<T>(() => {
    try { const i = localStorage.getItem(key); return i ? JSON.parse(i) : init; }
    catch { return init; }
  });
  return [s, v => { set(v); try { localStorage.setItem(key, JSON.stringify(v)); } catch {} }];
}

import { useEffect, useRef, useState } from "react";
export function useIntersection(opts?: IntersectionObserverInit) {
  const ref = useRef<Element|null>(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const o = new IntersectionObserver(([e]) => setVis(e.isIntersecting), opts);
    o.observe(el); return () => o.disconnect();
  }, []);
  return { ref, isIntersecting: vis };
}

import { useEffect, useRef } from "react";
export function useEventListener<K extends keyof WindowEventMap>(
  event: K, handler: (e: WindowEventMap[K]) => void, el: EventTarget = window
) {
  const ref = useRef(handler);
  useEffect(() => { ref.current = handler; }, [handler]);
  useEffect(() => {
    const fn = (e: Event) => ref.current(e as WindowEventMap[K]);
    el.addEventListener(event, fn);
    return () => el.removeEventListener(event, fn);
  }, [event, el]);
}

import React from "react";
interface P { fallback: React.ReactNode; children: React.ReactNode; }
export class ErrorBoundary extends React.Component<P, { err?: Error }> {
  state = {};
  static getDerivedStateFromError(err: Error) { return { err }; }
  componentDidCatch(e: Error, i: React.ErrorInfo) { console.error(e, i); }
