async function optimisticUpdate<T>(
  setState: React.Dispatch<React.SetStateAction<T>>,
  optimisticValue: T,
  apiCall: () => Promise<T>,
  rollback: T
): Promise<void> {
  setState(optimisticValue);
  try { setState(await apiCall()); }
  catch (err) { setState(rollback); throw err; }
}

