class Emitter {
  #e = new Map();
  on(ev, fn) { (this.#e.get(ev) ?? this.#e.set(ev, new Set()).get(ev)).add(fn); return this; }
  off(ev, fn) { this.#e.get(ev)?.delete(fn); return this; }
  once(ev, fn) { const w = (...a) => { fn(...a); this.off(ev, w); }; return this.on(ev, w); }
  emit(ev, ...a) { this.#e.get(ev)?.forEach(f => f(...a)); return this; }
}

